namespace HighscoreService.Hub.Api.Endpoints.Screens
{
        /// <summary>
        /// Request payload submitted by a screen server on first boot.
        /// </summary>
        /// <param name="ScreenId">Unique identifier generated by the screen.</param>
        /// <param name="NodeId">Human-readable node name.</param>
        /// <param name="MacAddress">Optional MAC address.</param>
        /// <param name="Secret">Auto-generated bearer secret (stored hashed on Hub).</param>
        public sealed record EnrollScreenRequest(
                Guid ScreenId,
                string NodeId,
                string? MacAddress,
                string Secret);
}

